require __DIR__.'/../../app/bootstrap.php';require_once __DIR__.'/../../app/api_v1.php';if(!setting_bool('mobile_api_enabled',true))api_json(['ok'=>false,'error'=>'Mobile API is disabled'],503);$in=api_input();$login=trim((string)($in['login']??''));$pass=(string)($in['password']??'');$device=trim((string)($in['device_name']??'Mobile App'))?:'Mobile App';try{security_assert_login_allowed($login);if($login===''||$pass==='')api_json(['ok'=>false,'error'=>'Login and password are required'],422);$q=db()->prepare('SELECT * FROM users WHERE (email=? OR phone=?) AND status=\'active\' LIMIT 1');$q->execute([$login,$login]);$u=$q->fetch();if(!$u||!password_verify($pass,$u['password_hash'])){security_record_login(false,$login,$u?(int)$u['id']:null,'mobile','Invalid credentials');api_json(['ok'=>false,'error'=>'Invalid credentials'],401);}if(function_exists('user_is_approved')&&!user_is_approved((int)$u['id'])){security_record_login(false,$login,(int)$u['id'],'mobile','Account not approved');api_json(['ok'=>false,'error'=>'Account is not approved for access'],403);}if(security_role_requires_2fa($u)){security_issue_otp($u,'mobile_api');$challenge='ch_'.bin2hex(random_bytes(24));db()->prepare("INSERT INTO mobile_api_challenges(user_id,challenge_hash,device_name,expires_at) VALUES(?,?,?,DATE_ADD(NOW(),INTERVAL 10 MINUTE))")->execute([(int)$u['id'],hash('sha256',$challenge),$device]);api_json(['ok'=>true,'two_factor_required'=>true,'challenge'=>$challenge]);}$token=api_issue_token((int)$u['id'],$device);security_record_login(true,$login,(int)$u['id'],'mobile');api_json(['ok'=>true,'two_factor_required'=>false,'auth'=>$token,'user'=>['id'=>(int)$u['id'],'name'=>$u['name'],'role'=>$u['role']]]);}catch(Throwable $e){api_json(['ok'=>false,'error'=>$e->getMessage()],429);}